package com.nm.fragmentsclean.experienceContext.read;
import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.Base64;import java.util.UUID;
public record ExperienceCursor(Instant createdAt,UUID id){public static ExperienceCursor parse(String value){if(value==null||value.isBlank())return null;try{String decoded=new String(Base64.getUrlDecoder().decode(value),StandardCharsets.UTF_8);int split=decoded.lastIndexOf('|');return new ExperienceCursor(Instant.parse(decoded.substring(0,split)),UUID.fromString(decoded.substring(split+1)));}catch(RuntimeException e){throw new IllegalArgumentException("Invalid experience cursor");}}public String encode(){return Base64.getUrlEncoder().withoutPadding().encodeToString((createdAt+"|"+id).getBytes(StandardCharsets.UTF_8));}}
